// Disassembly
////////////////////////////////
#define E(fmt, ...) tb_asm_print(e, fmt, ## __VA_ARGS__)
static void print_gpr_sp(TB_CGEmitter* e, int i, bool is_64bit) {
    if (i == ZR) {
        E("sp");
    } else if (i == LR) {
        E("lr");
    } else {
        E("%c%d", is_64bit["wx"], i);
    }
}

static void print_gpr(TB_CGEmitter* e, int i, bool is_64bit) {
    if (i == ZR) {
        E("zr");
    } else if (i == LR) {
        E("lr");
    } else {
        E("%c%d", is_64bit["wx"], i);
    }
}

static void dump_stack_layout(Ctx* restrict ctx, TB_CGEmitter* e) {

}

static bool sym_handler(TB_Disasm* disasm, int inst_length, uint64_t field, int field_pos, int field_len, bool is_offset) {
    return false;
}

// jcc 两条出边的真实概率（layout 用）；其余边给 0.0f 走默认
static float edge_prob(TB_Node* n) {
    TB_Node* tup = n->inputs[0];
    int index = TB_NODE_GET_EXTRA_T(n, TB_NodeProj)->index;

    if (tup->type == TB_a64_jcc || tup->type == TB_a64_jcc_imm) {
        A64Cond* op = TB_NODE_GET_EXTRA(tup);
        return index ? 1.0f - op->prob : op->prob;
    }
    return 0.0f;
}

// SLP 向量化钩子（NEON，128-bit 向量）。
// max_pack_width：每元素 lane 数与 x64 SSE 行一致（NEON 也是 128-bit）。
// is_pack_op_supported：发射层目前只实现了向量 ld/st 的 Q 形式编码
// （simd&fp LDR/STR），算术/搬移的 Q 形式尚未实现，所以只放行
// load/store，其余返回 0 让 slp 剪掉该 pack（不崩、不静默错码）。
// 注意必须 static：x64_target.c 里有同名全局符号，libtb 同时编进两个后端。
static int is_pack_op_supported(TB_Function* f, TB_DataType dt, TB_Node* n, int width) {
    int elem_bits = tb_data_type_bit_size(f->super.module, dt.type);
    int bits = elem_bits * width;
    switch (n->type) {
        case TB_LOAD:
        case TB_STORE:
        return bits == 128;

        // 浮点算术：NEON 三同 Q 形式已发射（f32x4/f64x2）
        case TB_FADD:
        case TB_FSUB:
        case TB_FMUL:
        case TB_FDIV:
        case TB_FMIN:
        case TB_FMAX:
        return bits == 128 && (dt.type == TB_TAG_F32 || dt.type == TB_TAG_F64);

        default:
        return 0;
    }
}

static int max_pack_width_for_op(TB_Function* f, TB_DataType dt, TB_Node* n) {
    static int limits[7] = { 16, 8, 4, 2, 0, 4, 2 };
    TB_ASSERT(dt.type >= 2);
    return limits[dt.type - 2];
}

ICodeGen tb__aarch64_codegen = {
    .minimum_addressable_size = 8,
    .pointer_size = 64,
    .global_init = global_init,
    .edge_prob = edge_prob,
    .print_extra = print_extra,
    .is_pack_op_supported = is_pack_op_supported,
    .max_pack_width_for_op = max_pack_width_for_op,
    .emit_win64eh_unwind_info = NULL,
    .emit_call_patches  = emit_call_patches,
    .compile_function   = compile_function,
};
